"use client";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./char-counter.css";

export type CharCounterProps = Omit<ComponentProps<"span">, "children"> & {
  /** How many characters are in the field. Pass the string's length. */
  length: number;
  /** The most the field allows. */
  max: number;
  /** The share of the limit at which the ring warns and the figure appears. */
  warnAt?: number;
};

/**
 * A character counter for a text box, drawn as a ring that fills as you type. It stays quiet and small until
 * you near the limit, when it turns amber and shows how many are left; past the limit it turns red and shows
 * how many are over, with one small nudge. Screen readers hear nothing while typing; they are told once when
 * the limit is near and once when it is passed. Link it to the field with `aria-describedby` on the field.
 * Under reduced motion the ring and figure change without moving.
 */
export function CharCounter({ length, max, warnAt = 0.85, className, ...props }: CharCounterProps) {
  const share = max > 0 ? length / max : 0;
  const state = length > max ? "over" : share >= warnAt ? "near" : "ok";
  const left = max - length;
  const [spoken, setSpoken] = useState("");
  const last = useRef(state);

  useEffect(() => {
    if (state === last.current) return;
    last.current = state;
    setSpoken(state === "over" ? `${-left} characters over the limit` : state === "near" ? `${left} characters left` : "");
  }, [state, left]);

  const radius = 8;
  const circumference = 2 * Math.PI * radius;
  const filled = Math.min(1, share) * circumference;
  return (
    <span data-slot="char-counter" data-state={state} className={cn("inline-flex items-center gap-2", className)} {...props}>
      <svg data-slot="chc-ring" viewBox="0 0 20 20" aria-hidden="true">
        <circle cx="10" cy="10" r={radius} data-slot="chc-track" />
        <circle cx="10" cy="10" r={radius} data-slot="chc-fill" strokeDasharray={`${filled} ${circumference}`} />
      </svg>
      {state !== "ok" && (
        <span data-slot="chc-figure" key={state} className="tabular-nums" aria-hidden="true">
          {left}
        </span>
      )}
      <span className="sr-only" role="status">
        {spoken}
      </span>
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* char-counter.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Char counter: the ring fills with length; near the limit it warns and shows what is left; past it, red. */
  [data-slot="char-counter"] { color: var(--muted-foreground); font-size: 13px; }
  [data-slot="char-counter"] [data-slot="chc-ring"] { width: 20px; height: 20px; flex: none; rotate: -90deg; }
  [data-slot="char-counter"] [data-slot="chc-ring"] circle { fill: none; stroke-width: 2.5px; }
  [data-slot="char-counter"] [data-slot="chc-track"] { stroke: var(--border); }
  [data-slot="char-counter"] [data-slot="chc-fill"] { stroke: currentColor; stroke-linecap: round; transition: stroke-dasharray var(--duration-deliberate) var(--ease-out), stroke var(--duration-normal) var(--ease-out); }
  [data-slot="char-counter"][data-state="near"] [data-slot="chc-fill"] { stroke: var(--warning); }
  [data-slot="char-counter"][data-state="over"] [data-slot="chc-fill"] { stroke: var(--destructive); }
  [data-slot="char-counter"][data-state="over"] [data-slot="chc-ring"] { animation: chc-nudge 0.32s var(--ease-out); }
  [data-slot="char-counter"] [data-slot="chc-figure"] { color: var(--foreground); font-weight: 500; animation: chc-pop var(--duration-deliberate) var(--ease-settle); }
  [data-slot="char-counter"][data-state="over"] [data-slot="chc-figure"] { color: var(--destructive); }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="char-counter"] :is([data-slot="chc-ring"], [data-slot="chc-figure"]) { animation: none; }
    [data-slot="char-counter"] [data-slot="chc-fill"] { transition: none; }
  }
  @keyframes chc-nudge { 30% { translate: -2px 0; } 65% { translate: 2px 0; } }
  @keyframes chc-pop { from { opacity: 0; scale: 0.7; } }
}
